import type { Catalogue, Restaurant } from './types';
import { loadCatalogue, browseRestaurants, norm, resolveArea } from './catalogue';

export interface Filters { region?: string; type?: string; area?: string; outdoor?: boolean; excludeType?: string }
export interface Page { items: Restaurant[]; total: number }
export interface CatalogueSource {
  readonly mode: 'supabase' | 'json';
  browse(query: string, filters?: Filters, offset?: number, limit?: number, signal?: AbortSignal): Promise<Page>;
  search(query: string, limit?: number, signal?: AbortSignal): Promise<Restaurant[]>;
  byId(licence: string, signal?: AbortSignal): Promise<Restaurant | null>;
  findByName(name: string, signal?: AbortSignal): Promise<Restaurant | null>;
  candidates(filters: Filters, signal?: AbortSignal): Promise<Catalogue>;
  count(filters?: Filters, signal?: AbortSignal): Promise<number>;
  peek(licence: string): Restaurant | null;
}

export class CatalogueError extends Error {
  constructor(public readonly kind: 'config' | 'network' | 'timeout' | 'access' | 'response', message: string) { super(message); }
}
export function catalogueErrorText(error: unknown): string {
  if (error instanceof CatalogueError) return error.message;
  return '餐廳資料暫時讀取唔到，請重試。本機記憶仍然保留。';
}

// Same ignored characters as legacy norm(), including the ECMAScript whitespace set.
// Only literal characters from the normalized query are inserted. % and _ stay literal.
const GAP = "[\u0009-\u000d \u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000\ufeff'()（）.,·&-]*";
export function namePattern(query: string): string {
  const q = norm(query);
  if (q.length > 120 || q.includes('\0')) throw new CatalogueError('response', '搜尋字句太長或含無效字元。');
  return [...q].map(c => c.replace(/[\\^$.*+?()[\]{}|]/g, '\\$&')).join(GAP);
}
// PostgREST reserved punctuation is protected independently from regex escaping.
export const quoteFilter = (value: string): string => '"' + value.replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';

interface Row {
  id: string; fehd_licence_no: string; name: string | null; name_en: string | null;
  district: string; region: string; licence_type: string; address: string | null;
  licence_expiry: string | null; info_codes: string[] | null; has_outdoor: boolean;
}
const validName = (name: string | null): string => name && !/^(?:n\/?a|null|undefined|nil|[-—]+)$/i.test(name.trim()) ? name.trim() : '';
export function adaptRestaurant(row: Row): Restaurant {
  if (!row.fehd_licence_no || !row.id) throw new CatalogueError('response', '餐廳資料缺少牌照識別碼。');
  const en = validName(row.name_en);
  const info = (row.info_codes ?? []).filter(c => c !== 'A');
  if (row.has_outdoor) info.push('A');
  return { id: row.fehd_licence_no, dbId: row.id, name: { tc: validName(row.name) || en || '未提供名稱', en },
    area: row.district, region: row.region, type: row.licence_type, addr: row.address ?? undefined,
    exp: row.licence_expiry ?? undefined, info };
}

class BoundedCache<T> {
  private values = new Map<string, { value: T; at: number }>();
  constructor(private max: number) {}
  get(key: string): T | undefined {
    const entry = this.values.get(key);
    if (!entry) return undefined;
    if (Date.now() - entry.at > 60_000) { this.values.delete(key); return undefined; }
    return entry.value;
  }
  set(key: string, value: T): void {
    this.values.delete(key);
    this.values.set(key, { value, at: Date.now() });
    while (this.values.size > this.max) this.values.delete(this.values.keys().next().value!);
  }
}

const SELECT = 'id,fehd_licence_no,name,name_en,district,region,licence_type,address,licence_expiry,info_codes,has_outdoor';
export class SupabaseCatalogue implements CatalogueSource {
  readonly mode = 'supabase' as const;
  private rows = new BoundedCache<Restaurant>(200);
  private pages = new BoundedCache<Page>(12);
  private counts = new BoundedCache<number>(12);
  constructor(private url: string, private key: string, private request: typeof fetch = fetch, private timeoutMs = 12_000) {}
  private validate(): void {
    if (!/^https:\/\/[a-z0-9]+\.supabase\.co\/?$/.test(this.url) || !this.key) throw new CatalogueError('config', '未設定公共餐廳連線；本機記憶仍可使用。');
    let role = '';
    if (this.key.startsWith('eyJ')) {
      try { role = JSON.parse(atob(this.key.split('.')[1].replace(/-/g, '+').replace(/_/g, '/'))).role; } catch { /* rejected below */ }
    }
    if (!this.key.startsWith('sb_publishable_') && role !== 'anon') throw new CatalogueError('config', '餐廳連線只接受公開 publishable／anon key。');
  }
  private params(query: string, filters: Filters): URLSearchParams {
    const p = new URLSearchParams({ select: SELECT, order: 'fehd_licence_no.asc,id.asc' });
    // Include the same public catalogue as the existing JSON; soft-deleted rows are excluded.
    p.set('deleted_at', 'is.null');
    p.set('fehd_licence_no', 'not.is.null');
    for (const [key, value] of [['region', filters.region], ['licence_type', filters.type], ['district', filters.area]] as const)
      if (value) p.set(key, `eq.${value}`);
    if (filters.excludeType && !filters.type) p.set('licence_type', `neq.${filters.excludeType}`);
    if (filters.outdoor) p.set('has_outdoor', 'eq.true');
    const pattern = namePattern(query);
    if (pattern) {
      const area = resolveArea(query);
      p.set('or', `(name.imatch.${quoteFilter(pattern)},name_en.imatch.${quoteFilter(pattern)}${area ? `,district.eq.${quoteFilter(area)}` : ''})`);
    }
    return p;
  }
  private async read(p: URLSearchParams, signal?: AbortSignal, head = false): Promise<Page> {
    this.validate();
    signal?.throwIfAborted();
    const controller = new AbortController();
    const abort = () => controller.abort(signal?.reason);
    signal?.addEventListener('abort', abort, { once: true });
    let timedOut = false;
    const timer = setTimeout(() => { timedOut = true; controller.abort(); }, this.timeoutMs);
    try {
      const request = this.request; // Native window.fetch must not receive the repository as `this`.
      const res = await request(`${this.url.replace(/\/$/, '')}/rest/v1/restaurants?${p}`, {
        method: head ? 'HEAD' : 'GET', headers: { apikey: this.key, Prefer: 'count=exact' }, signal: controller.signal,
      });
      if (res.status === 401 || res.status === 403) throw new CatalogueError('access', '公共餐廳讀取被拒絕，請檢查連線權限。');
      if (!res.ok) throw new CatalogueError('response', `餐廳服務回應錯誤（${res.status}），請重試。`);
      const range = res.headers.get('content-range');
      const rawTotal = range?.split('/')[1];
      if (!rawTotal || !/^\d+$/.test(rawTotal)) throw new CatalogueError('response', '餐廳服務未提供完整總數，請重試。');
      const items = head ? [] : (await res.json() as Row[]).map(adaptRestaurant);
      for (const r of items) this.rows.set(r.id, r);
      return { items, total: Number(rawTotal) };
    } catch (error) {
      if (signal?.aborted) throw signal.reason;
      if (timedOut) throw new CatalogueError('timeout', '餐廳服務逾時，請重試。');
      if (error instanceof CatalogueError) throw error;
      throw new CatalogueError('network', '網絡未能連接餐廳服務；本機記憶仍然保留。');
    } finally { clearTimeout(timer); signal?.removeEventListener('abort', abort); }
  }
  async browse(query: string, filters: Filters = {}, offset = 0, limit = 20, signal?: AbortSignal): Promise<Page> {
    signal?.throwIfAborted();
    const p = this.params(query, filters);
    p.set('offset', String(Math.max(0, Math.floor(offset))));
    p.set('limit', String(Math.min(250, Math.max(1, Math.floor(limit)))));
    const key = p.toString();
    const cached = this.pages.get(key);
    if (cached) return cached;
    const page = await this.read(p, signal);
    this.pages.set(key, page);
    return page;
  }
  async search(query: string, limit = 20, signal?: AbortSignal): Promise<Restaurant[]> {
    if (!norm(query)) return [];
    return (await this.browse(query, {}, 0, limit, signal)).items;
  }
  async findByName(name: string, signal?: AbortSignal): Promise<Restaurant | null> {
    if (!norm(name)) return null;
    const p = this.params('', {});
    const pattern = quoteFilter(namePattern(name));
    p.set('or', `(name.imatch.${pattern},name_en.imatch.${pattern})`);
    p.set('limit', '1');
    return (await this.read(p, signal)).items[0] ?? null;
  }
  peek(id: string): Restaurant | null { return this.rows.get(id) ?? null; }
  async byId(id: string, signal?: AbortSignal): Promise<Restaurant | null> {
    signal?.throwIfAborted();
    const cached = this.peek(id);
    if (cached) return cached;
    const p = this.params('', {});
    // Public IDs remain licence numbers. UUIDs never replace local-memory references.
    p.set('fehd_licence_no', `eq.${id}`);
    p.set('limit', '1');
    return (await this.read(p, signal)).items[0] ?? null;
  }
  async count(filters: Filters = {}, signal?: AbortSignal): Promise<number> {
    signal?.throwIfAborted();
    const p = this.params('', filters);
    p.set('limit', '1'); p.set('select', 'id');
    const cached = this.counts.get(p.toString());
    if (cached !== undefined) return cached;
    const total = (await this.read(p, signal, true)).total;
    this.counts.set(p.toString(), total);
    return total;
  }
  async candidates(filters: Filters, signal?: AbortSignal): Promise<Catalogue> {
    if (!filters.area) throw new CatalogueError('response', '請先揀推薦地區。');
    const items: Restaurant[] = [];
    const seen = new Set<string>();
    let total: number | undefined;
    do {
      const p = this.params('', filters);
      p.set('offset', String(items.length)); p.set('limit', '250');
      // Do not keep every district page in the browsing cache or mistake a server cap for EOF.
      const page = await this.read(p, signal);
      if (total !== undefined && total !== page.total) throw new CatalogueError('response', '餐廳資料更新中，請重試推薦。');
      total = page.total;
      if (!page.items.length && items.length < total) throw new CatalogueError('response', '餐廳候選未讀完，請重試。');
      for (const r of page.items) {
        if (seen.has(r.id)) throw new CatalogueError('response', '餐廳分頁已改變，請重試。');
        seen.add(r.id); items.push(r);
      }
    } while (items.length < total);
    return { source: 'Supabase / district candidates', generatedAt: '', count: items.length, restaurants: items };
  }
}

class JsonCatalogue implements CatalogueSource {
  readonly mode = 'json' as const;
  private cat: Catalogue | null = null;
  constructor(private baseUrl: string) {}
  private async load(): Promise<Catalogue> { return this.cat ??= await loadCatalogue(this.baseUrl); }
  async browse(query: string, filters: Filters = {}, offset = 0, limit = 20): Promise<Page> {
    const cat = await this.load();
    const scoped = { ...cat, restaurants: cat.restaurants.filter(r => (!filters.area || r.area === filters.area) && (!filters.excludeType || r.type !== filters.excludeType) && (!filters.outdoor || r.info?.includes('A'))) };
    const page = browseRestaurants(scoped, query, filters, offset + limit);
    return { items: page.items.slice(offset), total: page.total };
  }
  async search(query: string, limit = 20): Promise<Restaurant[]> { return norm(query) ? (await this.browse(query, {}, 0, limit)).items : []; }
  async findByName(name: string): Promise<Restaurant | null> {
    const cat = await this.load(); const q = norm(name);
    return q ? cat.restaurants.find(r => norm(r.name.tc).includes(q) || norm(r.name.en).includes(q)) ?? null : null;
  }
  async byId(id: string): Promise<Restaurant | null> { await this.load(); return this.peek(id); }
  peek(id: string): Restaurant | null { return this.cat?.restaurants.find(r => r.id === id) ?? null; }
  async count(filters: Filters = {}): Promise<number> { return (await this.browse('', filters, 0, 1)).total; }
  async candidates(filters: Filters): Promise<Catalogue> {
    const cat = await this.load();
    const page = await this.browse('', filters, 0, cat.count);
    return { ...cat, restaurants: page.items, count: page.total };
  }
}

export function createCatalogueSource(baseUrl: string): CatalogueSource {
  const mode = import.meta.env.VITE_CATALOGUE_SOURCE || 'supabase';
  if (mode === 'json') return new JsonCatalogue(baseUrl);
  // Configuration errors surface at the public-data boundary, never block local memories.
  if (mode !== 'supabase') return new SupabaseCatalogue('', '');
  return new SupabaseCatalogue(import.meta.env.VITE_SUPABASE_URL || '', import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY || '');
}
