// Reads the pre-cached「知名店」per hot area (server/famous-batch.mjs output).
// Values are FEHD ids only — names/data come from the app's FEHD catalogue, so a
// user pick is 0 Google calls and links straight to the detail page.
import { resolveArea } from "./catalogue";

let cache: Record<string, string[]> | null = null;
let byDistrict: Map<string, string[]> | null = null;

export async function loadFamous(baseUrl: string): Promise<void> {
  if (cache) return;
  try {
    const res = await fetch(`${baseUrl}data/famous.json`, { signal: AbortSignal.timeout(4000) });
    const d = await res.json();
    cache = (d && d.areas) || {};
  } catch {
    cache = {};
  }
  byDistrict = null;
}

/** FEHD ids of the prominent stores for a colloquial area (empty if none). */
export function famousFor(area: string): string[] {
  return cache?.[area] ?? [];
}

/** FEHD ids of prominent stores for a whole FEHD DISTRICT (union of the colloquial
 *  areas that resolve to it, prominence order preserved). Feeds the suggestion
 *  pool so 知名店 enter WITHOUT needing a name-keyword hit. */
export function famousForDistrict(district: string): string[] {
  if (!cache) return [];
  if (!byDistrict) {
    byDistrict = new Map();
    for (const [colloq, ids] of Object.entries(cache)) {
      const d = resolveArea(colloq) ?? colloq;
      const cur = byDistrict.get(d) ?? [];
      for (const id of ids) if (!cur.includes(id)) cur.push(id);
      byDistrict.set(d, cur);
    }
  }
  return byDistrict.get(district) ?? [];
}
